(function(){'use strict';var state={diffs:[],totalDiffs:0,addedCount:0,removedCount:0,modifiedCount:0,similarity:0,inputA:'',inputB:'',time:0,results:null,history:[]};var elements={};
function init(){elements={jsonA:document.getElementById('jc-json-a'),jsonB:document.getElementById('jc-json-b'),resultsDiv:document.getElementById('jc-results'),compareBtn:document.getElementById('compare-btn'),resetBtn:document.getElementById('reset-btn'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),historySection:document.getElementById('history-section'),historyList:document.getElementById('history-list'),statDiffs:document.getElementById('stat-diffs'),statAdded:document.getElementById('stat-added'),statRemoved:document.getElementById('stat-removed'),statModified:document.getElementById('stat-modified'),statSimilarity:document.getElementById('stat-similarity'),statTime:document.getElementById('stat-delta')};
if(elements.compareBtn)elements.compareBtn.addEventListener('click',compare);if(elements.resetBtn)elements.resetBtn.addEventListener('click',reset);
if(elements.jsonA)elements.jsonA.addEventListener('input',function(){if(elements.jsonA.value.trim()&&elements.jsonB.value.trim()){updateStatus('ready','Ready');}else{updateStatus('','');}});
if(elements.jsonB)elements.jsonB.addEventListener('input',function(){if(elements.jsonA.value.trim()&&elements.jsonB.value.trim()){updateStatus('ready','Ready');}else{updateStatus('','');}});
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);showEmptyState();}
function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}
function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}
function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}
function deepCompare(a,b,path,diffs){path=path||'';if(a===b)return;if(typeof a!==typeof b||Array.isArray(a)!==Array.isArray(b)||a===null||b===null){diffs.push({type:'modified',path:path||'(root)',oldVal:a,newVal:b});return;}
if(typeof a==='object'){var keys=Object.keys(a).concat(Object.keys(b)).filter(function(v,i,s){return s.indexOf(v)===i;});keys.forEach(function(k){var p=path?path+'.'+k:k;if(!(k in a))diffs.push({type:'added',path:p,oldVal:undefined,newVal:b[k]});else if(!(k in b))diffs.push({type:'removed',path:p,oldVal:a[k],newVal:undefined});else deepCompare(a[k],b[k],p,diffs);});}else if(a!==b){diffs.push({type:'modified',path:path,oldVal:a,newVal:b});}}
function calcSimilarity(totalKeys,diffCount){if(totalKeys===0)return 100;return Math.round((1-diffCount/totalKeys)*100);}
function countKeys(obj){if(typeof obj!=='object'||obj===null)return 1;var keys=Object.keys(obj);var total=keys.length;keys.forEach(function(k){total+=countKeys(obj[k]);});return total;}
function compare(){var textA=elements.jsonA.value.trim();var textB=elements.jsonB.value.trim();if(!textA||!textB){showToast('Please provide both JSON inputs','error');return;}
updateStatus('processing','Comparing...');var t0=performance.now();var objA,objB;
try{objA=JSON.parse(textA);}catch(e){showToast('Invalid JSON in A: '+e.message,'error');updateStatus('error','Error');return;}
try{objB=JSON.parse(textB);}catch(e){showToast('Invalid JSON in B: '+e.message,'error');updateStatus('error','Error');return;}
setTimeout(function(){var diffs=[];deepCompare(objA,objB,'',diffs);var t1=performance.now();
var added=diffs.filter(function(d){return d.type==='added';});var removed=diffs.filter(function(d){return d.type==='removed';});var modified=diffs.filter(function(d){return d.type==='modified';});
var totalKeys=countKeys(objA)+countKeys(objB);var similarity=calcSimilarity(totalKeys,diffs.length);
elements.resultsDiv.innerHTML='';if(diffs.length===0){elements.resultsDiv.innerHTML='<div style="text-align:center;padding:var(--space-4);color:var(--color-success);font-size:var(--text-lg);font-weight:600">JSONs are identical</div>';}else{diffs.forEach(function(d){var row=document.createElement('div');row.className='jc-diff-row';var bg='',prefix='';if(d.type==='added'){bg='background:rgba(34,197,94,0.12)';prefix='+ ';}else if(d.type==='removed'){bg='background:rgba(239,68,68,0.12)';prefix='- ';}else{bg='background:rgba(245,158,11,0.12)';prefix='~ ';}
var valHtml='';if(d.type==='added'){valHtml='<span class="jc-new">'+escapeHtml(formatVal(d.newVal))+'</span>';}else if(d.type==='removed'){valHtml='<span class="jc-old">'+escapeHtml(formatVal(d.oldVal))+'</span>';}else{valHtml='<span class="jc-old">'+escapeHtml(formatVal(d.oldVal))+'</span> <span class="jc-arrow">&rarr;</span> <span class="jc-new">'+escapeHtml(formatVal(d.newVal))+'</span>';}
row.innerHTML='<div class="jc-diff-path" style="'+bg+'"><span class="jc-diff-prefix">'+prefix+'</span><code>'+escapeHtml(d.path)+'</code></div><div class="jc-diff-values">'+valHtml+'</div>';elements.resultsDiv.appendChild(row);});}
var stats={diffs:diffs,totalDiffs:diffs.length,addedCount:added.length,removedCount:removed.length,modifiedCount:modified.length,similarity:similarity,inputA:textA.substring(0,80)+(textA.length>80?'...':''),inputB:textB.substring(0,80)+(textB.length>80?'...':''),time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
if(elements.statDiffs)elements.statDiffs.textContent=diffs.length;if(elements.statAdded)elements.statAdded.textContent=added.length;if(elements.statRemoved)elements.statRemoved.textContent=removed.length;if(elements.statModified)elements.statModified.textContent=modified.length;if(elements.statSimilarity)elements.statSimilarity.textContent=similarity+'%';if(elements.statTime)elements.statTime.textContent=(t1-t0)<1?'<1 ms':Math.round(t1-t0)+' ms';
var printTitle=document.querySelector('.print-report-title');var printDate=document.querySelector('.print-report-date');if(printTitle)printTitle.textContent='JSON Compare Report';if(printDate)printDate.textContent='Generated on '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
updateStatus('done','Completed');showResults();if(elements.exportSection)elements.exportSection.style.display='flex';renderComparison();renderHistory();},100);}
function formatVal(val){if(val===undefined)return'(undefined)';if(val===null)return'null';if(typeof val==='string')return'"'+val+'"';if(typeof val==='object')return JSON.stringify(val);return String(val);}
function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.inputA!==state.results.inputA||item.inputB!==state.results.inputB;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">Diffs: '+item.totalDiffs+' ('+item.similarity+'% similar)</option>';});
elements.comparisonSelect.innerHTML=html;}
function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var diffDiffs=curr.totalDiffs-prev.totalDiffs;var diffSim=curr.similarity-prev.similarity;
var metrics=[{label:'Total Diffs',curr:curr.totalDiffs,prev:prev.totalDiffs},{label:'Added',curr:curr.addedCount,prev:prev.addedCount},{label:'Removed',curr:curr.removedCount,prev:prev.removedCount},{label:'Modified',curr:curr.modifiedCount,prev:prev.modifiedCount},{label:'Similarity',curr:curr.similarity+'%',prev:prev.similarity+'%'},{label:'Time',curr:(curr.time<1?'<1 ms':Math.round(curr.time)+' ms'),prev:(prev.time<1?'<1 ms':Math.round(prev.time)+' ms')}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var diff=typeof m.curr==='number'&&typeof m.prev==='number'?m.curr-m.prev:0;
var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';
if(typeof m.curr==='string')arrow='<span class="comp-same">--</span>';html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}
function renderHistory(){if(!elements.historyList)return;
if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}
if(elements.historySection)elements.historySection.style.display='block';
var html='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];
var active=state.results&&item.inputA===state.results.inputA&&item.inputB===state.results.inputB?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';
html+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">Compared</span><span class="history-size">'+item.totalDiffs+' diffs</span></div><div class="history-lines">'+item.similarity+'% similar</div></div>';}
elements.historyList.innerHTML=html;}
function exportCopy(){if(!state.results)return;var r=state.results;var text='JSON Compare Report\n===================\n\nTotal Differences: '+r.totalDiffs+'\nAdded: '+r.addedCount+'\nRemoved: '+r.removedCount+'\nModified: '+r.modifiedCount+'\nSimilarity: '+r.similarity+'%\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nDiffs:\n';r.diffs.forEach(function(d){text+='  ['+d.type.toUpperCase()+'] '+d.path+'\n';if(d.oldVal!==undefined)text+='    Old: '+formatVal(d.oldVal)+'\n';if(d.newVal!==undefined)text+='    New: '+formatVal(d.newVal)+'\n';});
if(navigator.clipboard){navigator.clipboard.writeText(text.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(text.trim());}}
function exportTxt(){if(!state.results)return;var r=state.results;var text='JSON Compare Report\n===================\n\nTotal Differences: '+r.totalDiffs+'\nAdded: '+r.addedCount+'\nRemoved: '+r.removedCount+'\nModified: '+r.modifiedCount+'\nSimilarity: '+r.similarity+'%\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nDiffs:\n';r.diffs.forEach(function(d){text+='  ['+d.type.toUpperCase()+'] '+d.path+'\n';if(d.oldVal!==undefined)text+='    Old: '+formatVal(d.oldVal)+'\n';if(d.newVal!==undefined)text+='    New: '+formatVal(d.newVal)+'\n';});downloadFile('json-compare-report.txt',text,'text/plain');showToast('Downloaded TXT report','success');}
function exportJson(){if(!state.results)return;var obj={tool:'JSON Compare',totalDifferences:state.results.totalDiffs,added:state.results.addedCount,removed:state.results.removedCount,modified:state.results.modifiedCount,similarityPercentage:state.results.similarity,processingTimeMs:Math.round(state.results.time),timestamp:new Date().toISOString(),diffs:state.results.diffs.map(function(d){return{path:d.path,type:d.type,oldValue:d.oldVal,newValue:d.newVal};})};var json=JSON.stringify(obj,null,2);downloadFile('json-compare-report.json',json,'application/json');showToast('Downloaded JSON report','success');}
function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){if(elements.jsonA)elements.jsonA.value='';if(elements.jsonB)elements.jsonB.value='';if(elements.resultsDiv)elements.resultsDiv.innerHTML='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function escapeHtml(str){if(typeof str!=='string')return'';return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();